import json

with open('./data.json', 'r') as f:
    data = json.load(f)

# Extract employees and filter for HR department with salary > 80000
employees = data['employees']
hr_high_salary = [emp for emp in employees if emp.get('department') == 'HR' and emp.get('salary', 0) > 80000]

print(f"Number of HR employees with salary > 80000: {len(hr_high_salary)}")
print("\nDetails:")
for emp in hr_high_salary:
    print(emp)
